/*==============================================================*/
/* Table: "AcademicAssetMapping"                                */
/*==============================================================*/
create table "AcademicAssetMapping" (
   "mappingId"          INTEGER               not null,
   "schoolId"           INTEGER,
   "academicYearId"     INTEGER,
   "courseId"           INTEGER,
   "curriculumId"       INTEGER,
   "gradeLevelId"       INTEGER,
   "semesterId"         INTEGER,
   "assetType"          VARCHAR2(50),
   "assetCategoryId"    INTEGER,
   "assetId"            INTEGER,
   "assetName"          VARCHAR2(200),
   "assetDescription"   CLOB,
   "quantityPerStudent" VARCHAR2(50),
   "quantityPerClass"   VARCHAR2(50),
   "quantityPerSchool"  VARCHAR2(50),
   "ratio"              VARCHAR2(200),
   "ratioType"          VARCHAR2(50),
   "minRequiredQty"     VARCHAR2(200),
   "recommendedQty"     VARCHAR2(200),
   "currentAvailableQty" VARCHAR2(200),
   "shortageQty"        VARCHAR2(200),
   "priority"           VARCHAR2(200),
   "isCritical"         SMALLINT,
   "isNiceToHave"       SMALLINT,
   "preferredClassroomType" VARCHAR2(50),
   "requiredFacilities" VARCHAR2(200),
   "requiredSoftware"   VARCHAR2(200),
   "requiredConsumables" VARCHAR2(200),
   "specifications"     VARCHAR2(200),
   "standards"          VARCHAR2(200),
   "alternativeOptions" VARCHAR2(200),
   "notes"              CLOB,
   "createdByUserId"    INTEGER,
   "updatedByUserId"    INTEGER,
   "createdAt"          DATE,
   "updatedAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_ACADEMICASSETMAPPING primary key ("mappingId")
);

comment on table "AcademicAssetMapping" is
'الربط الأكاديمي والمنهجي';

comment on column "AcademicAssetMapping"."mappingId" is
'معرف الربط (المفتاح الرئيسي)';

comment on column "AcademicAssetMapping"."schoolId" is
'معرف المدرسة (FK → School.schoolId)';

comment on column "AcademicAssetMapping"."academicYearId" is
'معرف السنة الدراسية (FK → SchoolAcademicYear.academicYearId) - اختياري (للربط بسنة محددة)';

comment on column "AcademicAssetMapping"."courseId" is
'معرف المادة (FK → Course.courseId)';

comment on column "AcademicAssetMapping"."curriculumId" is
'معرف المنهج (FK → Curriculum.curriculumId) - اختياري';

comment on column "AcademicAssetMapping"."gradeLevelId" is
'معرف الصف (FK → GradeCapacity.gradeLevelId)';

comment on column "AcademicAssetMapping"."semesterId" is
'معرف الفصل (FK → SchoolSemester.semesterId) - اختياري';

comment on column "AcademicAssetMapping"."assetType" is
'نوع الأصل المطلوب (قاعة، معمل، جهاز، كتاب، برنامج، مستهلكات)';

comment on column "AcademicAssetMapping"."assetCategoryId" is
'معرف فئة الأصل (FK → AssetCategory.categoryId) - من قسم الأصول';

comment on column "AcademicAssetMapping"."assetId" is
'معرف أصل محدد (إن وجد) - اختياري';

comment on column "AcademicAssetMapping"."assetName" is
'اسم الأصل المطلوب (للوصف)';

comment on column "AcademicAssetMapping"."assetDescription" is
'وصف الأصل المطلوب';

comment on column "AcademicAssetMapping"."quantityPerStudent" is
'الكمية المطلوبة لكل طالب';

comment on column "AcademicAssetMapping"."quantityPerClass" is
'الكمية المطلوبة لكل فصل';

comment on column "AcademicAssetMapping"."quantityPerSchool" is
'الكمية المطلوبة للمدرسة ككل';

comment on column "AcademicAssetMapping"."ratio" is
'النسبة المعيارية (مثلاً: 1:2 تعني جهاز لكل طالبين)';

comment on column "AcademicAssetMapping"."ratioType" is
'نوع النسبة (طلاب:جهاز، طلاب:كتاب، فصول:معمل)';

comment on column "AcademicAssetMapping"."minRequiredQty" is
'الحد الأدنى المطلوب لتشغيل المقرر';

comment on column "AcademicAssetMapping"."recommendedQty" is
'الكمية الموصى بها';

comment on column "AcademicAssetMapping"."currentAvailableQty" is
'الكمية المتوفرة حالياً (حقل غير مخزن - يحسب آلياً)';

comment on column "AcademicAssetMapping"."shortageQty" is
'مقدار النقص (يحسب آلياً)';

comment on column "AcademicAssetMapping"."priority" is
'أولوية توفير هذا الأصل للمادة (عالية، متوسطة، منخفضة)';

comment on column "AcademicAssetMapping"."isCritical" is
'هل هو حرج (لا يمكن تدريس المادة بدونه)؟';

