/*==============================================================*/
/* Table: "AcademicException"                                   */
/*==============================================================*/
create table "AcademicException" (
   "exceptionId"        INTEGER               not null,
   "schoolId"           INTEGER,
   "academicYearId"     INTEGER,
   "requestType"        VARCHAR2(50),
   "studentId"          INTEGER,
   "affectedGroup"      VARCHAR2(200),
   "justification"      VARCHAR2(200),
   "supportingDocuments" VARCHAR2(200),
   "requestedStartDate" DATE,
   "requestedEndDate"   DATE,
   "expectedImpact"     VARCHAR2(200),
   "alternativePlan"    VARCHAR2(200),
   "status"             VARCHAR2(50),
   "submittedAt"        DATE,
   "submittedByUserId"  INTEGER,
   "officeDecision"     VARCHAR2(200),
   "decisionNotes"      CLOB,
   "decisionReference"  VARCHAR2(200),
   "decisionDate"       DATE,
   "approvedByUserId"   INTEGER,
   "expirationDate"     DATE,
   "isRenewable"        SMALLINT,
   "renewalCount"       INTEGER,
   "parentExceptionId"  INTEGER,
   "linkToWorkflowId"   INTEGER,
   "notes"              CLOB,
   "createdAt"          DATE,
   "createdByUserId"    INTEGER,
   "updatedAt"          DATE,
   "updatedByUserId"    INTEGER,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_ACADEMICEXCEPTION primary key ("exceptionId")
);

comment on table "AcademicException" is
'طلبات الاستثناءات الأكاديمية';

comment on column "AcademicException"."exceptionId" is
