   "passingGrade"       NUMBER(5,2),
   "evaluationCriteria" VARCHAR2(200),
   "resources"          VARCHAR2(200),
   "budget"             VARCHAR2(200),
   "isMandatory"        SMALLINT,
   "isGraded"           SMALLINT,
   "weight"             VARCHAR2(200),
   "status"             VARCHAR2(50),
   "completionRate"     NUMBER(5,2),
   "report"             VARCHAR2(200),
   "photos"             VARCHAR2(200),
