   "depreciableAmount"  NUMBER(15,2),
   "lastDepreciationDate" DATE,
   "lastDepreciationPeriod" VARCHAR2(200),
   "isFullyDepreciated" SMALLINT,
   "notes"              CLOB,
   "createdByUserId"    INTEGER,
   "updatedByUserId"    INTEGER,
   "createdAt"          DATE,
   "updatedAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_ASSETDEPRECIATION primary key ("depreciationId")
);

comment on table "AssetDepreciation" is
'سياسات وحسابات الإهلاك';

