comment on column "AssetDepreciation"."usefulLifeYears" is
'العمر الإنتاجي المقدر (بالسنوات) - يُستخدم لحساب قسط الإهلاك السنوي في طريقة القسط الثابت';

comment on column "AssetDepreciation"."usefulLifeUnits" is
