   "previousEnrollmentId" INTEGER,
   "enrollmentCode"     VARCHAR2(50),
   "enrollmentDateGregorian" DATE,
   "enrollmentSemester" VARCHAR2(200),
   "enrollmentSource"   VARCHAR2(200),
   "transferReason"     VARCHAR2(200),
   "transferFromSchool" VARCHAR2(200),
   "transferFromCity"   VARCHAR2(200),
   "transferFromCountry" INTEGER,
   "transferDocument"   VARCHAR2(200),
   "previousGradeLevel" NUMBER(5,2),
   "previousAcademicYear" VARCHAR2(200),
   "previousAverage"    VARCHAR2(200),
   "previousGrade"      NUMBER(5,2),
   "previousBehavior"   VARCHAR2(200),
   "hasPreviousRecord"  SMALLINT,
   "previousSchoolContact" VARCHAR2(200),
   "statusReason"       VARCHAR2(50),
   "statusDate"         DATE,
   "approvalDate"       DATE,
   "approvedByUserId"   INTEGER,
   "approvalNotes"      CLOB,
   "isActive"           SMALLINT,
   "isCurrent"          SMALLINT,
   "enrollmentFeePaid"  INTEGER,
