   "enrollmentFeeReceipt" NUMBER(15,2),
   "feeExemptionReason" NUMBER(15,2),
   "scholarshipType"    VARCHAR2(50),
   "scholarshipPercentage" NUMBER(5,2),
   "scholarshipSource"  VARCHAR2(200),
   "registrationComplete" VARCHAR2(200),
   "registrationCompletedAt" DATE,
   "documentsVerified"  VARCHAR2(200),
   "documentsVerifiedAt" DATE,
   "documentsVerifiedByUserId" INTEGER,
   "documentsNotes"     CLOB,
   "orientationSessionAttended" VARCHAR2(200),
   "orientationSessionDate" DATE,
   "contractSigned"     VARCHAR2(200),
   "contractSignedDate" DATE,
   "contractFilePath"   VARCHAR2(200),
   "studentHandbookAcknowledged" VARCHAR2(200),
   "handbookAcknowledgedDate" DATE,
   "medicalFormCompleted" VARCHAR2(200),
   "emergencyContactConfirmed" VARCHAR2(200),
   "pickupAuthorizedPersons" VARCHAR2(200),
   "busServiceSubscribed" VARCHAR2(200),
   "busRouteId"         INTEGER,
   "busStopId"          INTEGER,
   "mealPlanSubscribed" VARCHAR2(200),
   "mealPlanId"         INTEGER,
   "specialMealRequirements" VARCHAR2(200),
   "notes"              CLOB,
   "dataSource"         VARCHAR2(200),
   "importBatchId"      INTEGER,
   "createdByUserId"    INTEGER,
   "updatedAt"          DATE,
   "updatedByUserId"    INTEGER,
   "isDeleted"          SMALLINT,
   "deletedAt"          DATE,
   "deletedByUserId"    INTEGER,
   "-- FORE"            IGN KEY (`deletedByUserId`) REFERENCES `DeletedByUser`(`...`),
   constraint PK_ENROLLMENT primary key ("studentId")
);

