/*==============================================================*/
/* Table: "GuidanceSession"                                     */
/*==============================================================*/
create table "GuidanceSession" (
   "sessionId"          INTEGER               not null,
   "sessionNumber"      INTEGER,
   "counselorId"        INTEGER,
   "sessionType"        VARCHAR2(50),
   "category"           VARCHAR2(50),
   "title"              VARCHAR2(200),
   "objectives"         VARCHAR2(200),
   "plannedDate"        DATE,
   "actualDate"         DATE,
   "startTime"          DATE,
   "endTime"            DATE,
   "duration"           VARCHAR2(200),
   "location"           VARCHAR2(200),
   "isRecurring"        SMALLINT,
   "recurringPattern"   VARCHAR2(200),
   "parentSessionId"    INTEGER,
   "students"           VARCHAR2(200),
   "studentIds"         VARCHAR2(200),
   "attendeesCount"     INTEGER,
   "attendanceStatus"   VARCHAR2(50),
   "topics"             VARCHAR2(200),
   "summary"            VARCHAR2(200),
   "notes"              CLOB,
   "recommendations"    VARCHAR2(200),
   "actionPlan"         VARCHAR2(200),
   "followUpRequired"   VARCHAR2(200),
   "followUpDate"       DATE,
   "followUpNotes"      CLOB,
   "relatedDisciplineId" INTEGER,
   "relatedAcademicIssue" VARCHAR2(200),
   "progressBefore"     VARCHAR2(200),
   "progressAfter"      VARCHAR2(200),
   "progressRating"     VARCHAR2(200),
   "isConfidential"     SMALLINT,
   "sharedWithGuardian" VARCHAR2(200),
   "guardianNotified"   VARCHAR2(200),
   "guardianFeedback"   NUMBER(15,2),
   "attachments"        VARCHAR2(200),
   "createdByUserId"    INTEGER,
   "updatedByUserId"    INTEGER,
   "createdAt"          DATE,
   "updatedAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_GUIDANCESESSION primary key ("sessionId")
);

