/*==============================================================*/
/* Table: "HistoricalRecords"                                   */
/*==============================================================*/
create table "HistoricalRecords" (
   "recordId"           INTEGER               not null,
   "tableName"          VARCHAR2(200),
   "entityId"           INTEGER,
   "operationType"      VARCHAR2(50),
   "oldValue"           VARCHAR2(200),
   "newValue"           VARCHAR2(200),
   "fieldName"          VARCHAR2(200),
   "oldFieldValue"      VARCHAR2(200),
   "newFieldValue"      VARCHAR2(200),
   "changeReason"       VARCHAR2(200),
   "changeReasonCategory" VARCHAR2(50),
   "userId"             INTEGER,
   "userRole"           VARCHAR2(200),
   "userName"           VARCHAR2(200),
   "operationDate"      DATE,
   "ipAddress"          VARCHAR2(200),
   "deviceInfo"         VARCHAR2(200),
   "location"           VARCHAR2(200),
   "sessionId"          INTEGER,
   "affectedRowsCount"  INTEGER,
   "isReversible"       SMALLINT,
   "reversalRecordId"   INTEGER,
   "reversedAt"         DATE,
   "reversedByUserId"   INTEGER,
   "digitalSignature"   VARCHAR2(200),
   "riskScore"          NUMBER(5,2),
   "isHighRisk"         SMALLINT,
   "reviewedByAudit"    VARCHAR2(200),
   "auditReviewDate"    DATE,
   "auditReviewNotes"   CLOB,
   "retentionPeriodYears" VARCHAR2(200),
   "expiresAt"          DATE,
   "notes"              CLOB,
   "createdByUserId"    INTEGER,
   "createdAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`createdByUserId`) REFERENCES `CreatedByUser`(`...`),
   constraint PK_HISTORICALRECORDS primary key ("recordId")
);

