/*==============================================================*/
create table "KPI_Metrics" (
   "metricId"           INTEGER               not null,
   "configId"           INTEGER,
   "schoolId"           INTEGER,
   "academicYearId"     INTEGER,
   "periodType"         VARCHAR2(50),
   "periodValue"        VARCHAR2(200),
   "periodStartDate"    DATE,
   "periodEndDate"      DATE,
   "actualValue"        VARCHAR2(200),
   "targetValue"        VARCHAR2(200),
   "previousValue"      VARCHAR2(200),
   "changePercentage"   NUMBER(5,2),
   "statusColor"        VARCHAR2(50),
   "calculationMethod"  VARCHAR2(200),
   "calculationDate"    DATE,
   "calculatedByUserId" INTEGER,
   "dataSource"         VARCHAR2(200),
   "notes"              CLOB,
   "isVerified"         SMALLINT,
   "verifiedByUserId"   INTEGER,
   "verifiedAt"         VARCHAR2(200),
   "createdByUserId"    INTEGER,
   "updatedByUserId"    INTEGER,
   "createdAt"          DATE,
   "updatedAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_KPI_METRICS primary key ("metricId")
);

