/*==============================================================*/
/* Table: "StudentAccount"                                      */
/*==============================================================*/
create table "StudentAccount" (
   "accountId"          INTEGER               not null,
   "studentId"          INTEGER,
   "schoolId"           INTEGER,
   "academicYearId"     INTEGER,
   "accountNumber"      INTEGER,
   "totalDebit"         VARCHAR2(200),
   "totalCredit"        VARCHAR2(200),
   "currentBalance"     NUMBER(15,2),
   "balanceType"        NUMBER(15,2),
   "lastTransactionDate" DATE,
   "lastPaymentDate"    DATE,
   "lastPaymentAmount"  NUMBER(15,2),
   "accountStatus"      INTEGER,
   "isExempt"           SMALLINT,
   "exemptionPercentage" NUMBER(5,2),
   "exemptionReason"    VARCHAR2(200),
   "exemptionApprovedByUserId" INTEGER,
   "exemptionApprovalDate" DATE,
   "exemptionDocument"  VARCHAR2(200),
   "minimumPaymentRequired" VARCHAR2(200),
   "isBlockedFromRegistration" SMALLINT,
   "blockReason"        VARCHAR2(200),
   "unblockDate"        DATE,
   "paymentPlan"        VARCHAR2(200),
   "notes"              CLOB,
   "createdByUserId"    INTEGER,
   "updatedByUserId"    INTEGER,
   "createdAt"          DATE,
   "updatedAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_STUDENTACCOUNT primary key ("accountId")
);

