create table "SystemUser" (
   "userId"             INTEGER               not null,
   "schoolId"           INTEGER,
   "officeId"           INTEGER,
   "username"           VARCHAR2(200),
   "passwordHash"       VARCHAR2(200),
   "passwordSalt"       VARCHAR2(200),
   "passwordExpiryDate" DATE,
