   "phone"              VARCHAR2(20),
   "phoneVerified"      VARCHAR2(20),
   "phoneVerifiedAt"    DATE,
   "userType"           VARCHAR2(50),
   "employeeId"         INTEGER,
   "studentId"          INTEGER,
   "guardianId"         INTEGER,
   "twoFactorEnabled"   VARCHAR2(200),
