   "forecastedValue"    VARCHAR2(200),
   "forecastedValueNext" VARCHAR2(200),
   "confidenceLevel"    VARCHAR2(50),
   "lowerBound"         VARCHAR2(200),
   "upperBound"         VARCHAR2(200),
   "forecastingMethod"  VARCHAR2(200),
   "analysisDate"       DATE,
   "analyzedByUserId"   INTEGER,
   "notes"              CLOB,
   "status"             VARCHAR2(50),
   "approvedByUserId"   INTEGER,
   "approvalDate"       DATE,
   "createdByUserId"    INTEGER,
   "updatedByUserId"    INTEGER,
   "createdAt"          DATE,
   "updatedAt"          DATE,
   "isDeleted"          SMALLINT,
   "-- FORE"            IGN KEY (`updatedByUserId`) REFERENCES `UpdatedByUser`(`...`),
   constraint PK_TRENDANALYSISRESULT primary key ("analysisId")
);

